/**
 * RADRAFT — DIGITAL APPROVAL
 * Workflow 5
 *
 * Confirms successful Telegram delivery
 * and prepares an approved report for quota deduction.
 *
 * No Case ID required.
 */

const telegram = $('Send Final Report to Doctor').first().json;
const source = $('Data from Workflow 4').first().json;

// 1. Confirm Telegram successfully sent the report.
if (
  telegram.ok !== true ||
  !telegram.result?.document
) {
  throw new Error(
    'DIGITAL_APPROVAL: Final report was not successfully sent.'
  );
}

// 2. Obtain the authorized doctor's chat ID.
const chatId =
  source.chat_id ??
  telegram.result?.chat?.id ??
  null;

if (chatId === null || chatId === undefined || chatId === '') {
  throw new Error(
    'DIGITAL_APPROVAL: Missing Telegram chat ID.'
  );
}

// 3. Verify that an approved report was received.
const approvedReport = String(
  source.approved_report ?? ''
);

if (!approvedReport.trim()) {
  throw new Error(
    'DIGITAL_APPROVAL: Approved report is missing.'
  );
}

// 4. Preserve the approval timestamp.
// Never invent an approval time.
const approvedAt =
  source.approved_at ??
  source.approval_date ??
  null;

// 5. Return data for the subscription workflow.
return [{
  json: {
    chat_id: String(chatId),

    doctor_name:
      source.doctor_name ?? null,

    approved_report: approvedReport,

    approved_at: approvedAt,

    status: 'approved',

    delivery_status: 'sent',

    telegram_message_id:
      telegram.result.message_id ?? null,

    telegram_file_id:
      telegram.result.document.file_id ?? null,

    subscription_deduction_required: true
  }
}];

/**
 * CLEAN FINAL HTML REPORT
 * Accepts HTML from "Add patient details".
 * Removes unwanted AI text and Markdown fences.
 * Preserves patient details and doctor signature.
 */

return $input.all().map((item) => {

  // Read the HTML from the previous Code node.
  const raw = String(
    item.json.html ??
    item.json.output ??
    ''
  );

  if (!raw.trim()) {
    throw new Error(
      'No HTML content found in the input.'
    );
  }

  // Find the start of the HTML document.
  const start = raw.search(
    /<!doctype\s+html\b|<html\b/i
  );

  if (start === -1) {
    throw new Error(
      'No opening HTML document found.'
    );
  }

  // Find the closing HTML tag.
  const closingTag = /<\/html\s*>/gi;
  closingTag.lastIndex = start;

  const match = closingTag.exec(raw);

  if (!match) {
    throw new Error(
      'HTML closing tag not found.'
    );
  }

  // Extract only the complete HTML document.
  const html = raw
    .slice(start, match.index + match[0].length)
    .trim();

  // Confirm patient details and doctor name
  // placeholders have been replaced.
  const unresolved = html.match(
    /\{\{(?:PATIENT_NAME|PATIENT_AGE|REPORT_DATE|DOCTOR_NAME)\}\}/g
  );

  if (unresolved) {
    throw new Error(
      'Unresolved report placeholders: ' +
      [...new Set(unresolved)].join(', ')
    );
  }

  return {
    json: {
      ...item.json,
      html
    }
  };
});

/**
 * RADRAFT — ADD PATIENT DETAILS
 * Workflow 5: HTML report finalization
 *
 * Sources:
 * - HTML builder AI agent
 * - Data from Workflow 4
 *
 * Missing patient information remains blank.
 * No duplicate HTML sections are created.
 */

const source = $('Data from Workflow 4').first().json;
const report = $('HTML builder AI agent').first().json;

// Trusted patient metadata
const mapping = source.patient_metadata_mapping ?? {};
const metadata = source.patient_metadata_rest ?? {};

// Never infer patient identity from clinical wording.
// PERSON_1 must originate from a verified patient name.
const patientName = String(
  source.patient_name ??
  (source.patient_name_verified === true
    ? mapping['[PERSON_1]']
    : '') ??
  ''
).trim();

const patientDOB = String(
  source.patient_dob ??
  metadata.date_of_birth ??
  mapping['[DOB_1]'] ??
  ''
).trim();

const statedAge =
  source.patient_age ??
  metadata.stated_age ??
  null;

const doctorName = String(
  source.doctor_name ?? ''
).trim();

// Use the approval timestamp only when provided.
const timestamp =
  source.approved_at ??
  source.approval_date ??
  null;

const approvalDate = timestamp
  ? new Date(timestamp)
  : null;

const hasValidDate =
  approvalDate instanceof Date &&
  !Number.isNaN(approvalDate.getTime());

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function calculateAge(dob, referenceDate) {
  if (!dob || !referenceDate) return null;

  let year, month, day;

  let match = dob.match(
    /^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$/
  );

  if (match) {
    day = Number(match[1]);
    month = Number(match[2]);
    year = Number(match[3]);
  } else {
    match = dob.match(
      /^(\d{4})-(\d{2})-(\d{2})$/
    );

    if (!match) return null;

    year = Number(match[1]);
    month = Number(match[2]);
    day = Number(match[3]);
  }

  const birthDate = new Date(
    Date.UTC(year, month - 1, day)
  );

  if (
    birthDate.getUTCFullYear() !== year ||
    birthDate.getUTCMonth() !== month - 1 ||
    birthDate.getUTCDate() !== day
  ) {
    return null;
  }

  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Africa/Cairo',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(referenceDate);

  const value = type => Number(
    parts.find(part => part.type === type)?.value
  );

  let age = value('year') - year;

  if (
    value('month') < month ||
    (
      value('month') === month &&
      value('day') < day
    )
  ) {
    age--;
  }

  return age >= 0 && age <= 130 ? age : null;
}

const suppliedAge =
  statedAge !== null &&
  statedAge !== '' &&
  Number.isInteger(Number(statedAge)) &&
  Number(statedAge) >= 0 &&
  Number(statedAge) <= 130
    ? Number(statedAge)
    : null;

const age = suppliedAge ?? (
  hasValidDate
    ? calculateAge(patientDOB, approvalDate)
    : null
);

const formattedDate = hasValidDate
  ? new Intl.DateTimeFormat('en-GB', {
      timeZone: 'Africa/Cairo',
      day: '2-digit',
      month: 'long',
      year: 'numeric'
    }).format(approvalDate)
  : '';

// Extract standalone HTML.
const raw = String(
  report.output ?? report.html ?? ''
);

const start = raw.search(/<!doctype\s+html\b|<html\b/i);

if (start < 0) {
  throw new Error(
    'HTML_FINALIZATION_ERROR: HTML document not found.'
  );
}

const closing = /<\/html\s*>/gi;
closing.lastIndex = start;

const end = closing.exec(raw);

if (!end) {
  throw new Error(
    'HTML_FINALIZATION_ERROR: Closing HTML tag missing.'
  );
}

let html = raw.slice(
  start,
  end.index + end[0].length
);

// Fill existing placeholders only.
const replacements = {
  '{{PATIENT_NAME}}': escapeHtml(patientName),
  '{{PATIENT_AGE}}':
    age !== null ? `${age} years` : '',
  '{{REPORT_DATE}}': escapeHtml(formattedDate),
  '{{DOCTOR_NAME}}': escapeHtml(doctorName)
};

for (const [placeholder, replacement] of Object.entries(replacements)) {
  const count = html.split(placeholder).length - 1;

  if (count !== 1) {
    throw new Error(
      `HTML_FINALIZATION_ERROR: Expected one ${placeholder}, found ${count}.`
    );
  }

  html = html.replace(placeholder, replacement);
}

// Validate placeholder replacement.
if (
  /\{\{(?:PATIENT_NAME|PATIENT_AGE|REPORT_DATE|DOCTOR_NAME)\}\}/
    .test(html)
) {
  throw new Error(
    'HTML_FINALIZATION_ERROR: Unresolved placeholders.'
  );
}

return [{
  json: {
    html,

    chat_id:
      source.chat_id != null
        ? String(source.chat_id)
        : null,

    report_date: formattedDate,
    patient_name: patientName || null,
    patient_age: age,
    doctor_name: doctorName || null,

    patient_data_status:
      !patientName && age === null
        ? 'SKIPPED - No patient data provided'
        : !patientName || age === null
          ? 'PARTIAL - Missing patient fields left blank'
          : 'COMPLETE'
  }
}];
